insert into app.reviews (id, product_id, customer_id, order_id, display_name, location_label, avatar_url, rating, body, is_verified, status, is_sample, created_at) values
  ('63ee9378-b345-522f-aa9f-ad07f93fc3b2', null, null, null, 'Priya S.', 'Hatfield, Hertfordshire', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=150&q=80', 5, 'Amazing quality and super fast delivery. The produce always feels crisp, fresh, and hand-selected.', true, 'approved', true, '2026-11-19T00:00:00.000Z'),
  ('2bb178e9-0954-5ee7-8e1b-d224f8ae3561', null, null, null, 'Rahul K.', 'St Albans, Hertfordshire', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=150&q=80', 5, 'Best grocery experience I''ve had. Great selection, transparent sourcing, and remarkably easy to order.', true, 'approved', true, '2026-11-14T00:00:00.000Z'),
  ('f0b9fbe5-9088-5b64-b6e1-d670c2e2d911', null, null, null, 'Sneha M.', 'Welwyn Garden City', 'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=150&q=80', 5, 'FreshMart has made my weekly family shopping so much easier. The artisan bakery and eggs are second to none!', true, 'approved', true, '2026-11-18T00:00:00.000Z'),
  ('fe3996a1-2068-50ca-8380-13baedb68129', null, null, null, 'Oliver W.', 'Hertford, Hertfordshire', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=150&q=80', 5, 'The difference in flavour between supermarket produce and FreshMart is immediate. You can taste the care.', true, 'approved', true, '2026-11-16T00:00:00.000Z')
